// Some portions generated by Claude Code
package org.eclipse.rdf4j.sail.lmdb;

import static org.assertj.core.api.Assertions.assertThat;

import java.nio.file.Path;
import java.util.ArrayList;
import java.util.Arrays;
import java.util.Comparator;
import java.util.List;
import java.util.SplittableRandom;

import org.junit.jupiter.api.Test;
import org.junit.jupiter.api.io.TempDir;

class LmdbSortedRunsTest {

	@TempDir
	Path directory;

	@Test
	void mergedRunsComeOutInUnsignedFieldOrderWithDuplicatesSkipped() throws Exception {
		int[] posc = { 1, 2, 0, 3 };
		SplittableRandom random = new SplittableRandom(42);
		int rows = 5_000;
		long[] data = new long[4 * rows];
		for (int i = 0; i < rows; i++) {
			for (int f = 0; f < 4; f++) {
				// Few distinct values per field force duplicates; bit 63 is set on some, as for inline negative
				// doubles.
				long value = random.nextInt(6);
				data[4 * i + f] = value == 5 ? 0x8000_0000_0000_0001L : value;
			}
		}
		List<Path> runs = new ArrayList<>();
		for (int from = 0; from < rows; from += 1_700) {
			Path run = directory.resolve("run-" + from);
			LmdbSortedRuns.sortAndSpill(data, from, Math.min(rows, from + 1_700), posc, run);
			runs.add(run);
		}

		List<long[]> expected = new ArrayList<>();
		for (int i = 0; i < rows; i++) {
			expected.add(Arrays.copyOfRange(data, 4 * i, 4 * i + 4));
		}
		Comparator<long[]> order = (a, b) -> {
			for (int field : posc) {
				int c = Long.compareUnsigned(a[field], b[field]);
				if (c != 0) {
					return c;
				}
			}
			return 0;
		};
		expected.sort(order);
		List<long[]> distinct = new ArrayList<>();
		for (long[] row : expected) {
			if (distinct.isEmpty() || order.compare(distinct.get(distinct.size() - 1), row) != 0) {
				distinct.add(row);
			}
		}

		List<long[]> merged = new ArrayList<>();
		long duplicates;
		try (LmdbSortedRuns.Merge merge = new LmdbSortedRuns.Merge(runs, posc, true)) {
			long[] row = new long[4];
			while (merge.next(row)) {
				merged.add(row.clone());
			}
			duplicates = merge.duplicates();
		}
		assertThat(merged).containsExactlyElementsOf(distinct);
		assertThat(duplicates).isEqualTo(rows - distinct.size());
	}

	@Test
	void mergeKeepsDuplicatesWhenAskedAndHandlesEmptyRuns() throws Exception {
		int[] spoc = { 0, 1, 2, 3 };
		long[] data = { 3, 1, 1, 0, 1, 1, 1, 0, 3, 1, 1, 0, 2, 9, 9, 9 };
		Path first = directory.resolve("first");
		Path empty = directory.resolve("empty");
		LmdbSortedRuns.sortAndSpill(data, 0, 4, spoc, first);
		LmdbSortedRuns.sortAndSpill(data, 0, 0, spoc, empty);
		List<Long> subjects = new ArrayList<>();
		try (LmdbSortedRuns.Merge merge = new LmdbSortedRuns.Merge(List.of(empty, first), spoc, false)) {
			long[] row = new long[4];
			while (merge.next(row)) {
				subjects.add(row[0]);
			}
			assertThat(merge.duplicates()).isZero();
		}
		assertThat(subjects).containsExactly(1L, 2L, 3L, 3L);
	}
}
